CREATE TABLE IF NOT EXISTS repository_file_fingerprints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, repository_id uuid NOT NULL REFERENCES repositories ON DELETE CASCADE, file_path text NOT NULL, blob_sha text NOT NULL, normalized_sha256 text NOT NULL, observed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(repository_id,file_path,blob_sha));
CREATE TABLE IF NOT EXISTS repository_similarity_signals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, left_fingerprint uuid NOT NULL REFERENCES repository_file_fingerprints ON DELETE CASCADE, right_fingerprint uuid NOT NULL REFERENCES repository_file_fingerprints ON DELETE CASCADE, signal text NOT NULL, uncertainty text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(left_fingerprint,right_fingerprint));
CREATE INDEX IF NOT EXISTS repository_fingerprints_user_hash ON repository_file_fingerprints(user_id,normalized_sha256);
